update public.qb_questions q
set explain = q.explain || jsonb_build_object('references', d.refs, 'ref_links', d.links)
from d
where q.id = d.id and md5(coalesce(q.explain->>'references','')) in (d.old_md5, md5(d.refs));

update public.qb_questions q
set explain = jsonb_set(q.explain, '{summaries}', (
  select jsonb_agg(case when s ? 'refs' then jsonb_set(s, '{refs}', to_jsonb(replace(s->>'refs', $o$Sengupta N, et al. Management of patients with acute lower GI bleeding: updated ACG guideline. Am J Gastroenterol. 2023;118.$o$, $n$Sengupta N, et al. Management of patients with acute lower GI bleeding: updated ACG guideline. Am J Gastroenterol. 2023;118:208.$n$))) else s end order by ord)
  from jsonb_array_elements(q.explain->'summaries') with ordinality as t(s, ord)))
where q.id = 'Gastroenterology-3-08' and jsonb_typeof(q.explain->'summaries') = 'array';

-- 3b) complete the same citations everywhere else in the bank (same text, now with volume and first page)
insert into public.qb_refs_backup_20261110 (id, explain)
select id, explain from public.qb_questions where (strpos(explain::text, $o$Ghadri JR, et al. International expert consensus on takotsubo syndrome (Part II). Eur Heart J. 2018.$o$) > 0 or strpos(explain::text, $o$Gulati M, et al. 2021 AHA/ACC chest pain guideline. J Am Coll Cardiol. 2021.$o$) > 0 or strpos(explain::text, $o$Jones DW, et al. 2025 AHA/ACC high blood pressure guideline. J Am Coll Cardiol. 2025.$o$) > 0 or strpos(explain::text, $o$Kusumoto FM, et al. 2018 ACC/AHA/HRS bradycardia guideline. J Am Coll Cardiol. 2018.$o$) > 0 or strpos(explain::text, $o$Otto CM, et al. 2020 ACC/AHA valvular heart disease guideline. J Am Coll Cardiol. 2020.$o$) > 0 or strpos(explain::text, $o$Gornik HL, et al. 2024 ACC/AHA lower extremity PAD guideline. J Am Coll Cardiol. 2024.$o$) > 0 or strpos(explain::text, $o$Sengupta N, et al. Management of patients with acute lower GI bleeding: updated ACG guideline. Am J Gastroenterol. 2023;118.$o$) > 0 or strpos(explain::text, $o$Katz PO, et al. ACG clinical guideline: diagnosis and management of GERD. Am J Gastroenterol. 2022;117.$o$) > 0 or strpos(explain::text, $o$Terrault NA, et al. Update on prevention, diagnosis, and treatment of chronic hepatitis B: AASLD 2018 guidance. Hepatology. 2018.$o$) > 0 or strpos(explain::text, $o$CHEST 2025 guideline on RBC transfusion in critically ill adults (cited in your notes). Verify citation.$o$) > 0)
on conflict (id) do nothing;
update public.qb_questions set explain = replace(explain::text, $o$Ghadri JR, et al. International expert consensus on takotsubo syndrome (Part II). Eur Heart J. 2018.$o$, $n$Ghadri JR, et al. International expert consensus on takotsubo syndrome (Part II). Eur Heart J. 2018;39:2047.$n$)::jsonb where strpos(explain::text, $o$Ghadri JR, et al. International expert consensus on takotsubo syndrome (Part II). Eur Heart J. 2018.$o$) > 0;
