select count(*) as old_citations_left from public.qb_questions where strpos(explain::text, $o$Ghadri JR, et al. International expert consensus on takotsubo syndrome (Part II). Eur Heart J. 2018.$o$) > 0 or strpos(explain::text, $o$Gulati M, et al. 2021 AHA/ACC chest pain guideline. J Am Coll Cardiol. 2021.$o$) > 0 or strpos(explain::text, $o$Jones DW, et al. 2025 AHA/ACC high blood pressure guideline. J Am Coll Cardiol. 2025.$o$) > 0 or strpos(explain::text, $o$Kusumoto FM, et al. 2018 ACC/AHA/HRS bradycardia guideline. J Am Coll Cardiol. 2018.$o$) > 0 or strpos(explain::text, $o$Otto CM, et al. 2020 ACC/AHA valvular heart disease guideline. J Am Coll Cardiol. 2020.$o$) > 0 or strpos(explain::text, $o$Gornik HL, et al. 2024 ACC/AHA lower extremity PAD guideline. J Am Coll Cardiol. 2024.$o$) > 0 or strpos(explain::text, $o$Sengupta N, et al. Management of patients with acute lower GI bleeding: updated ACG guideline. Am J Gastroenterol. 2023;118.$o$) > 0 or strpos(explain::text, $o$Katz PO, et al. ACG clinical guideline: diagnosis and management of GERD. Am J Gastroenterol. 2022;117.$o$) > 0 or strpos(explain::text, $o$Terrault NA, et al. Update on prevention, diagnosis, and treatment of chronic hepatitis B: AASLD 2018 guidance. Hepatology. 2018.$o$) > 0 or strpos(explain::text, $o$CHEST 2025 guideline on RBC transfusion in critically ill adults (cited in your notes). Verify citation.$o$) > 0;

select count(*) filter (where q.explain ? 'ref_links') as with_links,
       count(*) as free_questions,
       sum(jsonb_array_length(q.explain->'ref_links')) as total_links,
       count(*) filter (where (q.explain->>'references') like '%Verify citation%') as placeholders_left
from public.qb_free_items i join public.qb_questions q on q.id = i.question_id;
